"""Ray Tracer Challenge - Number clamping utility
Source: ray_tracer_challenge/utilities.py
"""


def clamp_number(number: float, minimum: float, maximum: float) -> float:
    """Clamp number to [minimum, maximum] range."""
    if number >= maximum:
        return maximum
    elif number <= minimum:
        return minimum
    else:
        return number
